package com.jarvis.nextgen;
import com.jarvis.nextgen.*;import com.jarvis.nextgen.ProactiveEngine;import android.content.Context;import java.util.*;
public final class ProactiveTool implements Tool {private final ProactiveEngine e;public ProactiveTool(Context c){e=new ProactiveEngine(c);}public String name(){return "proactive";}public String description(){return "Enable or disable real proactive JARVIS notifications and morning briefing.";}public boolean canHandle(String s){String x=s.toLowerCase(Locale.ROOT);return x.contains("проактив")||x.contains("proactive")||x.contains("утренний обзор")||x.contains("morning briefing");}public Models.ToolResult execute(String s){String x=s.toLowerCase(Locale.ROOT);if(x.contains("выключ")||x.contains("отключ")||x.contains("disable")||x.contains("off")){e.disable();return Models.ToolResult.ok("Проактивные уведомления отключены.");}e.enable();return Models.ToolResult.ok("Проактивные уведомления включены. Утренний обзор и проверка ближайших событий активированы.");}}
